create table xxcus.xxfnd_lookup_values (
    lookup_type           varchar2(30 byte) not null enable,
    lookup_code           varchar2(30 byte) not null enable,
    meaning               varchar2(200 byte) not null enable,
    description           varchar2(500 byte),
    tag                   varchar2(150 byte),
    parent_lookup_type    varchar2(30 byte),
    parent_lookup_code    varchar2(30 byte),
    display_sequence      number,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    start_date_active     date default trunc(sysdate) not null enable,
    end_date_active       date,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_lookup_values
    add constraint xxfnd_lookup_values_ck1
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_lookup_values
    add constraint xxfnd_lookup_values_ck2
        check ( end_date_active is null
                or end_date_active >= start_date_active ) enable;

alter table xxcus.xxfnd_lookup_values
    add constraint xxfnd_lookup_values_pk primary key ( lookup_type,
                                                        lookup_code )
        using index enable;


